/*
 * A320927  Concatenation of successive segments generated by the morphism {0
 *          -> {0, 0, 1}, 1 -> {0,1,0}}, starting with 0.
 * https://oeis.org/A320927
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) is the nth term of the concatenation of successively
 *            applied morphisms 0 -> {0,0,1}, 1 -> {0,1,0}, starting from 0
 * Range:     u8 n <= 20000, u16 n <= 20000, u32 n <= 20000, u64 n <= 20000,
 *            u128 n <= 20000, big any n
 * Validated: standard, pass, 102 terms through n = 9276 (2026-11-01)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

static seq_t _seg_val(idx_t k, idx_t pos)
{
    /* Recursive computation of segment k value at position pos (0‑based). */
    if (k == 0)
        return 0;                 /* the initial segment is {0} */
    idx_t parent_pos = pos / 3;
    idx_t childIdx  = pos % 3;
    seq_t parent_val = _seg_val(k - 1, parent_pos);
    return (parent_val == 0)
           ? ((childIdx == 2) ? 1 : 0)   /* 0 -> {0,0,1} */
           : ((childIdx == 1) ? 1 : 0);  /* 1 -> {0,1,0} */
}

seq_t a(idx_t n)
{
    /* Segment lengths follow 3^k.  Find the segment that contains n. */
    idx_t cumulative = 0;          /* total length of all previous segments */
    idx_t length     = 1;          /* length of the current segment (3^k) */
    idx_t k          = 0;          /* current segment index */

    while (cumulative + length < n) {
        cumulative += length;
        length     *= 3;
        k++;
    }

    /* Position within the chosen segment (0‑based). */
    idx_t pos = n - cumulative - 1;
    return _seg_val(k, pos);
}
